        rs = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.8 * w]
        cs = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.8 * h]
        scores[color] = len(rs) + len(cs)
    line = max(scores, key=scores.get)
    rows = [r for r in range(h) if sum(v == line for v in grid[r]) >= 0.8 * w]
    cols = [c for c in range(w) if sum(grid[r][c] == line for r in range(h)) >= 0.8 * h]
    bg = Counter(v for row in grid for v in row if v != line).most_common(1)[0][0]
    out = []
    for i in range(len(rows) - 1):
        outrow = []
        for j in range(len(cols) - 1):
            corners = [grid[rows[i]][cols[j]], grid[rows[i]][cols[j+1]],
                       grid[rows[i+1]][cols[j]], grid[rows[i+1]][cols[j+1]]]
            if all(v != line and v == corners[0] for v in corners):
                outrow.append(corners[0])
            else:
                outrow.append(bg)
        out.append(outrow)
    return out
