def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)
    # Framework color has the fewest repeated near-solid row/column lines;
    # the dominant fill color also has many such rows/columns.
    candidates = []
    for color in colors:
        rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.7 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.7 * h]
        if len(rows) >= 2 and len(cols) >= 2:
            candidates.append((len(rows) * len(cols), len(rows) + len(cols), color, rows, cols))
    if not candidates:
        return [row[:] for row in grid]
    _, _, line, rows, cols = min(candidates)
    bg = Counter(v for row in grid for v in row if v != line).most_common(1)[0][0]
    out = []
    for i in range(len(rows) - 1):
        outrow = []
        for j in range(len(cols) - 1):
            corners = [grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                       grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]]]
            outrow.append(corners[0] if corners[0] != line and len(set(corners)) == 1 else bg)
        out.append(outrow)
    # Remove trailing empty output rows/columns, as in the examples.
    while out and all(v == bg for v in out[-1]):
        out.pop()
    if out:
        while all(row[-1] == bg for row in out):
            for row in out:
                row.pop()
    return out
